from pathlib import Path
import re

path = Path('/home/ubuntu/devora-frontend/client/src/pages/Home.tsx')
text = path.read_text()

# Remove the repository action but keep the page heading useful.
text = text.replace('<button className="primary-cta" onClick={() => toast.success("Repository parser queued for connection.")}><Upload size={16} /> Parse repository</button>', '<span className="subtle-btn repo-sync-badge"><i className="status-live" /> Context map synced</span>', 1)

# Replace AdminDashboard with a layout that has two explicit pair rings and the requested KPI language.
admin_pattern = r'function AdminDashboard\([\s\S]*?(?=\nfunction LearningPath)'
admin_replacement = '''function AdminDashboard({ onView, onHeatmap, onGapReview, onMember }: { onView: (view: View) => void; onHeatmap: () => void; onGapReview: () => void; onMember: (member: typeof members[number]) => void }) { return <div className="admin-dashboard"><section className="admin-overview"><div className="team-constellation"><div className="constellation-lines ring-maya-sofia" /><div className="constellation-lines ring-noah-aarav" /><div className="team-core"><Users size={22} /><strong>4</strong><small>Team Members</small></div>{members.map((member, index) => <button key={member.name} className={`constellation-member constellation-${index + 1}`} onClick={() => onMember(member)}><Avatar initials={member.initials} color={member.color} /><span>{member.name.split(" ")[0]}</span><small>{member.progress}%</small></button>)}</div><div className="admin-kpis"><div className="admin-kpi-card"><span className="eyebrow">PATH COMPLETION</span><strong>41<span>%</span></strong><small>+8% this week</small></div><div className="admin-kpi-card gap-kpi"><div><span className="eyebrow">KNOWLEDGE GAPS</span><strong>07</strong></div><button className="review-gaps-btn" onClick={onGapReview}>Review 3 gaps <ArrowUpRight size={13} /></button></div><div className="admin-kpi-card"><span className="eyebrow">ACTIVE TODAY</span><strong>03</strong><small>of 4 members</small></div></div></section><section className="admin-command-deck"><div className="command-deck-intro"><span className="eyebrow seafoam">ADMIN COMMAND DECK / LIVE SIGNAL</span><h2>Turn team signals into the next useful move.</h2><p>Choose a signal to inspect the people, context, or knowledge gap behind it.</p></div><div className="admin-command-grid"><button className="admin-command-card command-heat" onClick={onHeatmap}><span className="command-card-icon"><BrainCircuit size={18} /></span><span><b>Knowledge coverage</b><strong>6 categories mapped</strong><small>Explore the team heatmap</small></span><ArrowUpRight size={16} /></button><button className="admin-command-card command-focus" onClick={onGapReview}><span className="command-card-icon"><Sparkles size={18} /></span><span><b>Next intervention</b><strong>Authentication needs context</strong><small>Review Bob’s unanswered questions</small></span><ArrowUpRight size={16} /></button><button className="admin-command-card command-pulse" onClick={() => onView("notes")}><span className="command-card-icon"><MessageSquare size={18} /></span><span><b>Latest team pulse</b><strong>Taylor shared an API update</strong><small>Open the Notes feed</small></span><ArrowUpRight size={16} /></button></div></section></div>; }
'''
text, count = re.subn(admin_pattern, admin_replacement, text, count=1)
if count != 1:
    raise RuntimeError('AdminDashboard replacement failed')

# Replace NotesFeed with a local online-members reveal and cleaner admin treatment hook.
notes_pattern = r'function NotesFeed\(\) \{[\s\S]*?(?=\n\nfunction Repository)'
notes_replacement = '''function NotesFeed() { const [showOnline, setShowOnline] = useState(false); const notes = [{initials:"TS",color:"#f3b56b",name:"Taylor Swift",role:"Team admin",time:"09:42",text:"The API glossary is ready for review. I added the auth edge cases Bob was missing."},{initials:"MC",color:"#8cf7d0",name:"Maya Chen",role:"Frontend engineer",time:"10:06",text:"Perfect — I’m moving through Local Setup now. The checkpoint is clear."},{initials:"AS",color:"#9eaaff",name:"Aarav Shah",role:"Backend engineer",time:"10:31",text:"Architecture module unlocked on my side. The request flow diagram helped a lot."}]; return <><div className="page-heading"><div><p className="eyebrow">TEAM COMMUNICATION / LIVE</p><h1>Notes feed</h1><p>Questions, updates, and small signals from the people building Atlas Core.</p></div><button className={`subtle-btn online-toggle ${showOnline ? "active" : ""}`} onClick={() => setShowOnline((current) => !current)}><Users size={16} /> 4 members online <ChevronDown size={14} /></button></div>{showOnline && <div className="online-members-panel"><div><span className="eyebrow">LIVE TEAM PULSE</span><h3>Who is online now</h3></div><div className="online-member-list">{members.filter((_, index) => index < 3).map((member) => <div key={member.name}><Avatar initials={member.initials} color={member.color} /><span><strong>{member.name}</strong><small>{member.role}</small></span><i /></div>)}</div></div>}<div className="notes-shell"><div className="notes-stream"><div className="stream-day">TODAY · THURSDAY</div>{notes.map((note) => <div className={`feed-note ${note.role === "Team admin" ? "admin-note" : ""}`} key={note.time}><Avatar initials={note.initials} color={note.color} /><div><div className="feed-meta"><strong>{note.name}</strong><time>{note.time}</time></div><small className="feed-role">{note.role}</small><p>{note.text}</p></div></div>)}</div><div className="composer-panel"><span className="eyebrow">NEW NOTE</span><textarea placeholder="Share an update with the team..." /><div><span>⌘ ↵ to send</span><button className="primary-cta" onClick={() => toast.success("Note ready to send once the API is connected.")}>Post note <ArrowUpRight size={15} /></button></div></div></div></>; }'''
text, count = re.subn(notes_pattern, notes_replacement, text, count=1)
if count != 1:
    raise RuntimeError('NotesFeed replacement failed')

# Replace MemberStatus with the detailed panel below the four-person list.
member_pattern = r'function MemberStatus\([\s\S]*?(?=\nfunction KnowledgeGapReview)'
member_replacement = '''function MemberStatus({ focus, setFocus }: { focus: Member; setFocus: (member: Member) => void }) { const moduleRows = [{name:"Project Overview",completion:100,time:"18 min",last:"Mon 09:12"},{name:"Local Setup",completion:focus.progress > 55 ? 100 : 68,time:"24 min",last:"Today 10:06"},{name:"Architecture",completion:focus.progress > 65 ? 74 : 18,time:"16 min",last:"Yesterday 16:40"},{name:"APIs & Data Flow",completion:focus.progress > 75 ? 44 : 0,time:"—",last:"Not started"}]; const status = focus.progress >= 60 ? {label:"On track",color:"#8cf7d0"} : focus.progress >= 35 ? {label:"At risk",color:"#f3b56b"} : {label:"Needs attention",color:"#ff7c8c"}; return <><div className="page-heading"><div><p className="eyebrow">ADMIN / TEAM HEALTH</p><h1>Member status</h1><p>See where each developer is in their onboarding journey.</p></div></div><div className="members-layout members-stack"><div className="member-table creative-member-list">{members.map((member) => <button key={member.name} className={`${focus.name === member.name ? "selected" : ""} ${member.progress < 35 ? "needs-attention" : ""}`} onClick={() => setFocus(member)}><Avatar initials={member.initials} color={member.color} /><span><strong>{member.name}</strong><small>{member.role}</small></span><div className="member-progress"><span><i style={{ width: `${member.progress}%`, background: member.color }} /></span><b>{member.progress}%</b></div><ChevronRight size={16} /></button>)}</div><div className="member-detail rich-member-detail"><div className="member-detail-head"><Avatar initials={focus.initials} color={focus.color} /><div><h2>{focus.name}</h2><p>{focus.role} · joined 6 days ago</p></div><span className="member-health" style={{ color: status.color, borderColor: `${status.color}80`, background: `${status.color}12` }}><i style={{ background: status.color }} />{status.label}</span></div><div className="member-identity-grid"><span><small>TEAM ID</small><strong>atlas-core</strong></span><span><small>ROLE</small><strong>{focus.role}</strong></span><span><small>LAST ACTIVE</small><strong>{focus.name === "Maya Chen" ? "Today · 10:06" : "Yesterday · 16:40"}</strong></span></div><section className="member-section"><div className="section-head"><div><span className="eyebrow">ONBOARDING PROGRESS</span><h3>Module by module</h3></div><strong className="member-percent">{focus.progress}%</strong></div><div className="member-module-list">{moduleRows.map((row) => <div key={row.name}><span><strong>{row.name}</strong><small>{row.time} · last accessed {row.last}</small></span><b>{row.completion}%</b><i><em style={{ width: `${row.completion}%`, background: focus.color }} /></i></div>)}</div></section><section className="member-section assistant-activity"><div className="section-head"><div><span className="eyebrow">AI ASSISTANT ACTIVITY</span><h3>Questions that shape the Twin</h3></div><BrainCircuit size={17} /></div><div className="activity-stat-grid"><span><strong>24</strong><small>questions asked</small></span><span><strong>7</strong><small>hints used</small></span><span><strong>Auth</strong><small>most frequent topic</small></span></div><p><Sparkles size={14} /> Potential knowledge gap: <b>Authentication and Authorization</b></p></section><section className="member-section engagement-section"><div className="section-head"><div><span className="eyebrow">ACTIVITY & ENGAGEMENT</span><h3>This week’s rhythm</h3><small className="engagement-note">Calculated from completed modules, tasks, and active learning days.</small></div><Zap size={17} /></div><div className="engagement-bars">{[["Mon",22],["Tue",38],["Wed",18],["Thu",68],["Fri",84],["Sat",28],["Sun",42]].map(([day, value]) => <span key={day}><i style={{ height: `${value}%` }} /><small>{day}</small></span>)}</div><div className="engagement-meta"><span><strong>3</strong> modules completed</span><span><strong>5</strong> day learning streak</span><span><strong>8</strong> tasks completed</span></div></section><div className="admin-summary"><span className="eyebrow">DEVORA SUMMARY</span><p>{focus.name} is progressing {focus.progress >= 60 ? "well overall" : "steadily"} but shows a knowledge gap in authentication and database architecture. Recommend completing the Authentication module before proceeding to Deployment.</p></div></div></div></>; }'''
text, count = re.subn(member_pattern, member_replacement, text, count=1)
if count != 1:
    raise RuntimeError('MemberStatus replacement failed')

path.write_text(text)
print('admin refinements applied')
